export class TauriTerminalTransport implements TerminalTransport {
  async listSessions() {
    const sessions = await listTerminalSessions();
    return sessions.map((s) => ({
      sessionId: s.sessionId,
      worktreePath: s.worktreePath,
    }));
  }

  async attach(sessionId: string): Promise<TerminalAttachment> {
    return { sessionId };
  }

  async write(sessionId: string, data: string | Uint8Array) {
    const text = typeof data === "string" ? data : new TextDecoder().decode(data);
    await writeTerminal({ sessionId, data: text });
  }

  async resize(sessionId: string, cols: number, rows: number) {
    await resizeTerminal({ sessionId, cols, rows });
  }

  async signal(sessionId: string, signal: "interrupt" | "terminate" | "kill") {
    await signalTerminal({ sessionId, signal });
  }

  async close(sessionId: string) {
    await closeTerminal(sessionId);
  }

  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe {
    let unlisten: (() => void) | null = null;
    let cancelled = false;

    onTerminalOutput((payload) => {
      if (payload.sessionId === sessionId) {
        listener(payload.data);
      }
    }).then((fn) => {
      if (cancelled) {
        fn();
      } else {
        unlisten = fn;
      }
    });

    return () => {
      cancelled = true;
      if (unlisten) {
        unlisten();
      }
    };
  }

  onLifecycle(listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe {
    let unlisten: (() => void) | null = null;
    let cancelled = false;

    onTerminalLifecycle((payload) => {
      listener({
        sessionId: payload.sessionId,
        state: payload.state,
        exitCode: payload.exitCode,
      });
    }).then((fn) => {
      if (cancelled) {
        fn();
      } else {
        unlisten = fn;
      }
    });

    return () => {
      cancelled = true;
      if (unlisten) {
        unlisten();
      }
    };
  }
}

export const defaultTauriTransport = new TauriTerminalTransport();

import {
  createTerminalInstance,
  disposeTerminalInstance,
  fitTerminal,
  type TerminalInstance,
} from "./terminalInstanceFactory";
import { attachScheduledOutputSubscription, MAX_PENDING_OUTPUT_CHARS } from "./terminalOutputScheduler";
import {
  applyTerminalSettings,
  type EffectiveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type { TerminalInstance };
export { MAX_PENDING_OUTPUT_CHARS };

export const DEFAULT_WARM_CACHE_LIMIT = 2;

type SpawnGeneration = {
  generation: number;
  activeCount: number;
};

class TerminalHostManager {
  private instances = new Map<string, TerminalInstance>();
  private pendingSpawns = new Map<string, Promise<TerminalInstance>>();
  private spawnGenerations = new Map<string, SpawnGeneration>();
  private visibleRefCounts = new Map<string, number>();
  private inactiveLruSessionIds: string[] = [];
  private warmCacheLimit = DEFAULT_WARM_CACHE_LIMIT;

  setWarmCacheLimit(limit: number): void {
    this.warmCacheLimit = Math.max(0, limit);
    this.evictInactiveIfNeeded();
  }

  getWarmCacheLimit(): number {
    return this.warmCacheLimit;
  }

  isSessionVisible(sessionId: string): boolean {
    return (this.visibleRefCounts.get(sessionId) ?? 0) > 0;
  }

  registerVisible(sessionId: string): () => void {
    const current = this.visibleRefCounts.get(sessionId) ?? 0;
    this.visibleRefCounts.set(sessionId, current + 1);
    if (current === 0) {
      this.markSessionVisible(sessionId);
    }
    let unregistered = false;
    return () => {
      if (unregistered) return;
      unregistered = true;
      const count = (this.visibleRefCounts.get(sessionId) ?? 1) - 1;
      if (count <= 0) {
        this.visibleRefCounts.delete(sessionId);
        this.markSessionInactive(sessionId);
      } else {
        this.visibleRefCounts.set(sessionId, count);
      }
    };
  }

  setVisible(sessionId: string, visible: boolean): void {
    if (visible) {
      const current = this.visibleRefCounts.get(sessionId) ?? 0;
      this.visibleRefCounts.set(sessionId, Math.max(1, current));
      this.markSessionVisible(sessionId);
    } else {
      this.visibleRefCounts.delete(sessionId);
      this.markSessionInactive(sessionId);
    }
  }

  private markSessionVisible(sessionId: string): void {
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    const inst = this.instances.get(sessionId);
    if (inst) {
      if (!inst.unsubscribeOutput) {
        inst.terminal.reset();
        if (inst.session.backendSessionId) {
          inst.unsubscribeOutput = attachScheduledOutputSubscription(inst.session.backendSessionId, inst.terminal);
        }
      }
    }
  }

  private markSessionInactive(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      inst.unsubscribeOutput?.();
      inst.unsubscribeOutput = undefined;
    }
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.inactiveLruSessionIds.push(sessionId);
    this.evictInactiveIfNeeded();
  }

  private evictInactiveIfNeeded(): void {
    while (this.inactiveLruSessionIds.length > this.warmCacheLimit) {
      const oldestSessionId = this.inactiveLruSessionIds.shift();
      if (!oldestSessionId) break;
      this.disposeFrontendInstance(oldestSessionId);
    }
  }

  private disposeFrontendInstance(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      this.instances.delete(sessionId);
      disposeTerminalInstance(inst);
    }
  }

  getInstance(sessionId: string): TerminalInstance | undefined {
    return this.instances.get(sessionId);
  }

  async getOrCreate(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const isVisible = this.isSessionVisible(session.id);
    const existing = this.instances.get(session.id);
    if (existing) {
      existing.session = session;
      existing.active = active;
      existing.onBell = onBell;
      existing.onTitleChange = onTitleChange;

      if (isVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!existing.unsubscribeOutput) {
          existing.terminal.reset();
          if (session.backendSessionId) {
            existing.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, existing.terminal);
          }
        }
      } else {
        if (existing.unsubscribeOutput) {
          existing.unsubscribeOutput();
          existing.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return existing;
    }

    const pending = this.pendingSpawns.get(session.id);
    if (pending) return pending;

    const currentGen = this.spawnGenerations.get(session.id);
    const generation = (currentGen ? currentGen.generation : 0) + 1;
    const activeCount = (currentGen ? currentGen.activeCount : 0) + 1;
    this.spawnGenerations.set(session.id, { generation, activeCount });

    const spawnPromise = createTerminalInstance({
      session,
      active,
      isVisible: this.isSessionVisible(session.id),
      onBell,
      onTitleChange,
      getInstance: (id) => this.instances.get(id),
    });
    this.pendingSpawns.set(session.id, spawnPromise);

    try {
      const instance = await spawnPromise;
      if (this.spawnGenerations.get(session.id)?.generation !== generation) {
        disposeTerminalInstance(instance);
        return instance;
      }

      this.instances.set(session.id, instance);

      const stillVisible = this.isSessionVisible(session.id);
      if (stillVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!instance.unsubscribeOutput && session.backendSessionId) {
          instance.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, instance.terminal);
        }
      } else {
        if (instance.unsubscribeOutput) {
          instance.unsubscribeOutput();
          instance.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return instance;
    } finally {
      const tracking = this.spawnGenerations.get(session.id);
      if (tracking) {
        tracking.activeCount -= 1;
        if (tracking.activeCount <= 0) {
          this.spawnGenerations.delete(session.id);
        }
      }
      if (this.pendingSpawns.get(session.id) === spawnPromise) {
        this.pendingSpawns.delete(session.id);
      }
    }
  }

  updateSession(sessionId: string, session: TerminalSession) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      const prevBackendId = inst.session.backendSessionId;
      inst.session = session;
      const isVisible = this.isSessionVisible(sessionId);
      if (isVisible) {
        if (session.backendSessionId !== prevBackendId) {
          inst.unsubscribeOutput?.();
          inst.unsubscribeOutput = undefined;
          if (session.backendSessionId) {
            inst.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, inst.terminal);
          }
        }
      } else {
        if (inst.unsubscribeOutput) {
          inst.unsubscribeOutput();
          inst.unsubscribeOutput = undefined;
        }
      }
    }
  }

  applyInstanceSettings(sessionId: string, settings: EffectiveTerminalSettings) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        fitTerminal(inst.terminal, inst.fitAddon);
      }
    }
  }

  applySettings(settings: EffectiveTerminalSettings) {
    for (const inst of this.instances.values()) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        fitTerminal(inst.terminal, inst.fitAddon);
      }
    }
  }

  destroy(sessionId: string) {
    const tracking = this.spawnGenerations.get(sessionId);
    if (tracking) {
      tracking.generation += 1;
    }
    this.visibleRefCounts.delete(sessionId);
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.pendingSpawns.delete(sessionId);
    this.disposeFrontendInstance(sessionId);
  }
}

export const terminalHostManager = new TerminalHostManager();

import { createLayoutState, normalizeLayout } from "../state/layout";
import { collectLeafIds, createLeafNode } from "../state/paneTree";
import type { WorkspaceState } from "../state/workspaceStore";
import { loadBrowserSettings } from "./browserSettings";
import {
  worktreeIdentity,
  type BrowserTab,
  type LayoutState,
  type PersistedLayout,
  type PersistedTab,
  type PersistedTerminalSession,
  type PersistedWorkspace,
  type PersistedWorkspaceSession,
  type PersistedWorktree,
  type TabGroup,
  type TerminalSession,
  type TerminalTab,
  type WorkspaceTab,
  type Worktree,
} from "./types";

export const WORKSPACE_SESSION_VERSION = 2;

export function serializeWorkspaceState(
  workspaceId: string,
  repoRoot: string,
  state: WorkspaceState,
  existingSession?: PersistedWorkspaceSession | null,
): PersistedWorkspaceSession {
  const browserSettings = loadBrowserSettings();
  const restoreBrowserTabs = browserSettings.restoreTabsOnLaunch;

  const persistedWorktrees: PersistedWorktree[] = state.worktrees.map((wt) => ({
    path: wt.path,
    branch: wt.branch ?? "",
    head: wt.head,
    isMain: !wt.branch || wt.branch === "main" || wt.branch === "master",
    isLocked: Boolean(wt.locked),
  }));

  function serializeLayout(layoutState: LayoutState): PersistedLayout {
    const normalizedLayout = normalizeLayout(layoutState);
    const persistedTabs: PersistedTab[] = [];
    for (const tab of normalizedLayout.tabs) {
      if (tab.kind === "browser") {
        if (!restoreBrowserTabs) continue;
        persistedTabs.push({
          id: tab.id,
          kind: "browser",
          label: tab.label,
          pinned: Boolean(tab.pinned),
          browser: {
            browserId: tab.browserId,
            url: tab.url,
            title: tab.title ?? null,
            loading: tab.loading,
            canGoBack: tab.canGoBack,
            canGoForward: tab.canGoForward,
            profileId: tab.profileId,
            worktreePath: tab.worktreePath,
            worktreeLabel: tab.worktreeLabel,
          },
        });
        continue;
      }

      const tabLayout = normalizedLayout.layoutsByTabId[tab.id];
      persistedTabs.push({
        id: tab.id,
        kind: "terminal",
        label: tab.label,
        pinned: Boolean(tab.pinned),
        terminal: tabLayout
          ? {
              primarySessionId: tab.sessionId,
              paneTree: tabLayout.root,
              sessionIdsByLeafId: { ...tabLayout.sessionIdsByLeafId },
              activeLeafId: tabLayout.activeLeafId,
              expandedLeafId: tabLayout.expandedLeafId,
            }
          : {
              primarySessionId: tab.sessionId,
              paneTree: createLeafNode(`leaf-persisted:${tab.id}`),
              sessionIdsByLeafId: { [`leaf-persisted:${tab.id}`]: tab.sessionId },
              activeLeafId: `leaf-persisted:${tab.id}`,
              expandedLeafId: null,
            },
      });
    }

    const tabIds = new Set(persistedTabs.map((t) => t.id));
    const activeTabId =
      normalizedLayout.activeTabId && tabIds.has(normalizedLayout.activeTabId)
        ? normalizedLayout.activeTabId
        : (persistedTabs[0]?.id ?? null);
    const primaryTabId =
      normalizedLayout.primaryTabId && tabIds.has(normalizedLayout.primaryTabId)
        ? normalizedLayout.primaryTabId
        : (persistedTabs[0]?.id ?? null);

    return {
      splitMode: normalizedLayout.split ?? "none",
      primaryTabId,
      secondaryTabId: normalizedLayout.secondaryTabId ?? null,
      activeTabId,
      tabs: persistedTabs,
      tabGroups: Object.values(normalizedLayout.tabGroups ?? {}).map((group) => ({
        id: group.id,
        tabIds: group.tabIds.filter((id) => tabIds.has(id)),
        activeTabId: group.activeTabId && tabIds.has(group.activeTabId) ? group.activeTabId : null,
      })),
      tabGroupLayout: normalizedLayout.tabGroupLayout ?? null,
      focusedGroupId: normalizedLayout.focusedGroupId ?? null,
    };
  }

  const persistedLayout = serializeLayout(state.layout);
  const persistedWorktreeLayouts: Record<string, PersistedLayout> = {};
  for (const [wtPath, layout] of Object.entries(state.worktreeLayouts ?? {})) {
    if (layout) {
      persistedWorktreeLayouts[wtPath] = serializeLayout(layout);
    }
  }

  const allPersistedLayouts = [persistedLayout, ...Object.values(persistedWorktreeLayouts)];
  const referencedSessionIds = new Set<string>();
  for (const layout of allPersistedLayouts) {
    for (const tab of layout.tabs) {
      if (tab.kind === "browser") continue;
      const terminal = tab.terminal;
      if (terminal?.primarySessionId) referencedSessionIds.add(terminal.primarySessionId);
      for (const sessionId of Object.values(terminal?.sessionIdsByLeafId ?? {})) {
        if (sessionId) referencedSessionIds.add(sessionId);
      }
    }
  }

  const persistedTerminalSessions: Record<string, PersistedTerminalSession> = {};
  const createdAt = Date.now();
  for (const [id, sess] of Object.entries(state.sessions)) {
    if (!sess || !referencedSessionIds.has(id)) continue;
    persistedTerminalSessions[id] = {
      localSessionId: sess.id,
      backendSessionId: sess.backendSessionId,
      worktreePath: sess.worktreePath ?? sess.cwd,
      cwd: sess.cwd,
      createdAt,
    };
  }

  const workspace: PersistedWorkspace = {
    workspaceId,
    repoRoot,
    worktrees: persistedWorktrees,
    activeWorktreePath: state.activeWorktreePath,
    layout: persistedLayout,
    ...(Object.keys(persistedWorktreeLayouts).length > 0 ? { worktreeLayouts: persistedWorktreeLayouts } : {}),
    terminalSessions: persistedTerminalSessions,
  };

  const workspaces = {
    ...(existingSession?.workspaces ?? {}),
    [workspaceId]: workspace,
  };

  return {
    version: WORKSPACE_SESSION_VERSION,
    timestamp: Date.now(),
    activeWorkspaceId: workspaceId,
    workspaces,
  };
}

export function deserializeWorkspaceState(
  workspaceId: string,
  persistedSession: PersistedWorkspaceSession,
  liveBackendSessionIds?: Iterable<string> | null,
): WorkspaceState | null {
  const ws = persistedSession.workspaces?.[workspaceId];
  if (!ws) return null;
  const isV2 = (persistedSession.version ?? 1) >= 2;

  const browserSettings = loadBrowserSettings();
  const restoreBrowser = browserSettings.restoreTabsOnLaunch;
  const knownProfiles = new Set(browserSettings.profiles.map((p) => p.id));
  const fallbackProfileId = browserSettings.defaultProfileId;

  const liveSet = liveBackendSessionIds
    ? (liveBackendSessionIds instanceof Set ? liveBackendSessionIds : new Set(liveBackendSessionIds))
    : null;

  const worktrees: Worktree[] = (ws.worktrees || []).map((wt) => ({
    path: wt.path,
    branch: wt.branch ? (wt.branch.startsWith("refs/heads/") ? wt.branch : `refs/heads/${wt.branch}`) : null,
    head: wt.head,
    bare: false,
    detached: false,
    locked: wt.isLocked ? "locked" : null,
    prunable: null,
  }));

  const sessions: Record<string, TerminalSession> = {};
  for (const [mapKey, sess] of Object.entries(ws.terminalSessions || {})) {
    const localSessionId = sess.localSessionId || mapKey || sess.sessionId || "";
    if (!localSessionId) continue;
    const persistedBackendSessionId = isV2 ? (sess.backendSessionId ?? null) : (sess.backendSessionId ?? sess.sessionId ?? null);
    const backendSessionId = liveSet
      ? (persistedBackendSessionId && liveSet.has(persistedBackendSessionId) ? persistedBackendSessionId : null)
      : persistedBackendSessionId;
    const worktreePath = sess.worktreePath || sess.cwd;
    const matchingWorktree = worktrees.find((wt) => wt.path === worktreePath);
    sessions[localSessionId] = {
      id: localSessionId,
      cwd: sess.cwd || worktreePath,
      worktreePath,
      workspaceId,
      worktree: matchingWorktree ? worktreeIdentity(matchingWorktree) : null,
      backendSessionId,
      lifecycle: backendSessionId ? "working" : "exited",
    };
  }

  function deserializeLayout(persistedLayout: PersistedLayout | undefined): LayoutState {
    if (!persistedLayout) return createLayoutState();

    const tabs: WorkspaceTab[] = [];
    for (const persistedTab of persistedLayout.tabs || []) {
      if (persistedTab.kind === "browser" || persistedTab.browser) {
        if (!restoreBrowser) continue;
        const browser = persistedTab.browser;
        const rawProfileId = browser?.profileId;
        const profileId = rawProfileId && knownProfiles.has(rawProfileId) ? rawProfileId : fallbackProfileId;
        const tab: BrowserTab = {
          id: persistedTab.id,
          kind: "browser",
          label: persistedTab.label,
          browserId: browser?.browserId ?? persistedTab.sessionId ?? `restored-browser:${persistedTab.id}`,
          url: browser?.url ?? "about:blank",
          title: browser?.title ?? persistedTab.label,
          canGoBack: browser?.canGoBack ?? false,
          canGoForward: browser?.canGoForward ?? false,
          loading: browser?.loading ?? false,
          pinned: Boolean(persistedTab.pinned),
          profileId,
          worktreePath: browser?.worktreePath ?? persistedTab.worktreePath,
          worktreeLabel: browser?.worktreeLabel,
        };
        tabs.push(tab);
        continue;
      }

      const primarySessionId = persistedTab.terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
      const tab: TerminalTab = {
        id: persistedTab.id,
        kind: "terminal",
        sessionId: primarySessionId,
        label: persistedTab.label,
        pinned: Boolean(persistedTab.pinned),
      };
      tabs.push(tab);
    }

    const layoutsByTabId: LayoutState["layoutsByTabId"] = {};
    for (const persistedTab of persistedLayout.tabs || []) {
      if (persistedTab.kind === "browser" || persistedTab.browser) {
        if (!restoreBrowser) continue;
        const leafId = `leaf-browser:${persistedTab.id}`;
        layoutsByTabId[persistedTab.id] = {
          root: createLeafNode(leafId),
          activeLeafId: leafId,
          expandedLeafId: null,
          sessionIdsByLeafId: { [leafId]: "" },
        };
        continue;
      }

      const terminal = persistedTab.terminal;
      const legacyTabLayout = persistedLayout.layoutsByTabId?.[persistedTab.id];
      const paneTree = terminal?.paneTree ?? persistedTab.paneTree ?? legacyTabLayout?.root;
      const primarySessionId = terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
      const root = paneTree ?? createLeafNode(`leaf-restored:${persistedTab.id}`);
      const leafIds = collectLeafIds(root);
      const persistedMapping =
        terminal?.sessionIdsByLeafId ?? persistedTab.sessionIdsByLeafId ?? legacyTabLayout?.sessionIdsByLeafId;
      const sessionIdsByLeafId = persistedMapping && Object.keys(persistedMapping).length > 0
        ? Object.fromEntries(leafIds.map((leafId) => [leafId, persistedMapping[leafId] ?? primarySessionId]))
        : Object.fromEntries(leafIds.map((leafId) => [leafId, primarySessionId]));
      const requestedActiveLeafId =
        terminal?.activeLeafId ?? persistedTab.activeLeafId ?? legacyTabLayout?.activeLeafId ?? null;
      const requestedExpandedLeafId =
        terminal?.expandedLeafId ?? persistedTab.expandedLeafId ?? legacyTabLayout?.expandedLeafId ?? null;
      layoutsByTabId[persistedTab.id] = {
        root,
        activeLeafId: requestedActiveLeafId && leafIds.includes(requestedActiveLeafId) ? requestedActiveLeafId : leafIds[0] ?? null,
        expandedLeafId:
          requestedExpandedLeafId && leafIds.includes(requestedExpandedLeafId) ? requestedExpandedLeafId : null,
        sessionIdsByLeafId,
      };
    }

    const tabGroups: Record<string, TabGroup> | undefined = persistedLayout.tabGroups?.length
      ? Object.fromEntries(
          persistedLayout.tabGroups.map((group) => [
            group.id,
            { id: group.id, tabIds: [...group.tabIds], activeTabId: group.activeTabId },
          ]),
        )
      : undefined;

    return normalizeLayout({
      tabs,
      primaryTabId: persistedLayout.primaryTabId || (tabs[0]?.id ?? null),
      secondaryTabId: persistedLayout.secondaryTabId || null,
      activeTabId: persistedLayout.activeTabId || (tabs[0]?.id ?? null),
      split: (persistedLayout.splitMode as LayoutState["split"]) || "none",
      nestedSplit: null,
      layoutsByTabId,
      tabGroups,
      tabGroupLayout: persistedLayout.tabGroupLayout ?? null,
      focusedGroupId: persistedLayout.focusedGroupId ?? null,
    });
  }

  const activeLayout = deserializeLayout(ws.layout);
  const worktreeLayouts: Record<string, LayoutState> = {};
  if (ws.worktreeLayouts) {
    for (const [wtPath, persistedWtLayout] of Object.entries(ws.worktreeLayouts)) {
      if (persistedWtLayout) {
        worktreeLayouts[wtPath] = deserializeLayout(persistedWtLayout);
      }
    }
  }

  const allLayouts = [activeLayout, ...Object.values(worktreeLayouts)];
  const referencedSessionIds = new Set<string>();
  for (const layout of allLayouts) {
    for (const tab of layout.tabs) {
      if (tab.kind === "browser") continue;
      if (tab.sessionId) referencedSessionIds.add(tab.sessionId);
      const tabLayout = layout.layoutsByTabId[tab.id];
      for (const sessionId of Object.values(tabLayout?.sessionIdsByLeafId ?? {})) {
        if (sessionId) referencedSessionIds.add(sessionId);
      }
    }
  }

  const referencedSessions = Object.fromEntries(
    Object.entries(sessions).filter(([sessionId]) => referencedSessionIds.has(sessionId)),
  );

  return {
    worktrees,
    activeWorktreePath: ws.activeWorktreePath || (worktrees[0]?.path ?? null),
    sessions: referencedSessions,
    layout: activeLayout,
    worktreeLayouts,
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

import type { PaneDirection, PaneNode } from "../state/paneTree";

export type WorktreeIdentity = {
  wsId: string;
  slug: string;
};

export type Worktree = {
  path: string;
  head: string;
  branch: string | null;
  bare: boolean;
  detached: boolean;
  locked: string | null;
  prunable: string | null;
};

export function worktreeIdentity(worktree: Worktree): WorktreeIdentity | null {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "");
  const parts = branch?.split("/");
  if (!parts || parts.length < 3 || parts[0] !== "orca") return null;

  return { wsId: parts[1], slug: parts.slice(2).join("/") };
}

export type DirtyFile = {
  statusCode: string;
  path: string;
};

export type DirtyState = {
  isDirty: boolean;
  files: DirtyFile[];
};

export type BranchDeletionPreview = {
  branch: string;
  head: string;
  upstream: string | null;
  merged: boolean;
  ahead: number | null;
  behind: number | null;
};

