describe("HMR session retention boundary", () => {
  beforeEach(() => {
    clearHmrWorkspaceState?.();
  });

  it("synchronously seeds useWorkspaceStore from HMR handoff and preserves active/parked layouts across runtime refresh", async () => {
    const workspaceId = "ws-1";
    const initialFullState = buildTestWorkspaceState(workspaceId);
    const { storeServices, runtimeServices } = createMockServices();

    // 1. Establish live state in pre-HMR session and verify dispatch sync
    const firstMount = renderHook(() => {
      const store = useWorkspaceStore({ workspaceId, services: storeServices });
      const runtime = useWorkspaceRuntime({
        workspaceId,
        activeWorktreePath: store.state.activeWorktreePath,
        syncWorktrees: store.syncWorktrees,
        ensureTabForWorktree: store.ensureTabForWorktree,
        services: runtimeServices,
      });
      return { store, runtime };
    });

    // Populate initial state into the first mount
    act(() => {
      firstMount.result.current.store.restoreWorkspace(initialFullState);
    });

    // Verify state before HMR
    expect(firstMount.result.current.store.state.layout.tabs).toHaveLength(2);
    expect(firstMount.result.current.store.state.worktreeLayouts?.["/repo/feature"]?.tabs).toHaveLength(2);

    // Verify HMR registry captured the state synchronously at dispatch seam
    const captured = getHmrWorkspaceState(workspaceId);
    expect(captured).not.toBeNull();
    expect(captured?.sessions["session-main-1"]?.backendSessionId).toBe("backend-main-1");

    // 2. Simulate HMR lifecycle: unmount old React tree (simulating Vite Fast Refresh / module reload)
    firstMount.unmount();

    // Reset service mocks to ensure HMR remount does not spawn unnecessary fallback terminals
    storeServices.spawnTerminal = vi.fn(async () => "unexpected-new-spawn");
    storeServices.closeTerminal = vi.fn(async () => undefined);

    // 3. Remount fresh store + runtime (post-HMR module reload)
    const secondMount = renderHook(() => {
      const store = useWorkspaceStore({ workspaceId, services: storeServices });
      const runtime = useWorkspaceRuntime({
        workspaceId,
        activeWorktreePath: store.state.activeWorktreePath,
        syncWorktrees: store.syncWorktrees,
        ensureTabForWorktree: store.ensureTabForWorktree,
        services: runtimeServices,
      });
      return { store, runtime };
    });

    // Initial synchronous state on mount MUST already have the full hydrated state BEFORE refresh
    const initialHydrated = secondMount.result.current.store.state;
    expect(initialHydrated.activeWorktreePath).toBe("/repo/main");
    expect(initialHydrated.layout.tabs).toHaveLength(2);
    expect(initialHydrated.worktreeLayouts?.["/repo/feature"]?.tabs).toHaveLength(2);

    // Allow runtime refreshWorktrees effect to run
    await act(async () => {
      await secondMount.result.current.runtime.refreshWorktrees();
    });

    const finalState = secondMount.result.current.store.state;

    // Assert active worktree & layout
    expect(finalState.activeWorktreePath).toBe("/repo/main");
    expect(finalState.layout.tabs).toHaveLength(2);
    expect(finalState.layout.tabs[0]).toMatchObject({
      id: "tab-term-main",
      label: "main-term",
      sessionId: "session-main-1",
    });
    expect(finalState.layout.tabs[1]).toMatchObject({
      kind: "browser",
      id: "tab-browser-main",
      label: "Frontend Dev",
      browserId: "browser-dev-1",
      url: "http://localhost:5173",
      title: "App Preview",
      worktreePath: "/repo/main",
    });

    // Assert active split pane structure & leaf session mapping
    const activeTabLayout = finalState.layout.layoutsByTabId["tab-term-main"];
    expect(activeTabLayout).toBeDefined();
    expect(activeTabLayout.root).toEqual({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-1" },
      second: { type: "leaf", leafId: "leaf-2" },
      ratio: 0.6,
    });
    expect(activeTabLayout.sessionIdsByLeafId).toEqual({
      "leaf-1": "session-main-1",
      "leaf-2": "session-main-2",
    });

    // Assert parked worktree layout & tabs
    expect(finalState.worktreeLayouts?.["/repo/feature"]).toBeDefined();
    const parkedLayout = finalState.worktreeLayouts!["/repo/feature"];
    expect(parkedLayout.tabs).toHaveLength(2);
    expect(parkedLayout.tabs[0]).toMatchObject({
      id: "tab-term-feature",
      label: "feature-term",
      sessionId: "session-feature-1",
    });
    expect(parkedLayout.tabs[1]).toMatchObject({
      kind: "browser",
      id: "tab-browser-feature",
      label: "Docs",
      browserId: "browser-docs-1",
      url: "http://localhost:3000",
      worktreePath: "/repo/feature",
    });

    // Assert all session metadata preserved (CWD, worktree identity, backendSessionId, lifecycle)
    expect(finalState.sessions["session-main-1"]).toEqual({
      id: "session-main-1",
      cwd: "/repo/main",
      worktreePath: "/repo/main",
      workspaceId: "ws-1",
      worktree: { wsId: "ws-1", slug: "main" },
      backendSessionId: "backend-main-1",
      lifecycle: "working",
    });

    expect(finalState.sessions["session-main-2"]).toEqual({
      id: "session-main-2",
      cwd: "/repo/main/packages/api",
      worktreePath: "/repo/main",
      workspaceId: "ws-1",
      worktree: { wsId: "ws-1", slug: "main" },
      backendSessionId: "backend-main-2",
      lifecycle: "working",
    });

    expect(finalState.sessions["session-feature-1"]).toEqual({
      id: "session-feature-1",
      cwd: "/repo/feature",
      worktreePath: "/repo/feature",
      workspaceId: "ws-1",
      worktree: { wsId: "ws-1", slug: "feature" },
      backendSessionId: "backend-feature-1",
      lifecycle: "working",
    });

    // Ensure no spurious backend terminal spawns occurred during HMR recovery
    expect(storeServices.spawnTerminal).not.toHaveBeenCalled();
    expect(storeServices.closeTerminal).not.toHaveBeenCalled();
  });

  it("isolates HMR handoff strictly to the matching workspace ID", async () => {
    const ws1State = buildTestWorkspaceState("ws-alpha");
    setHmrWorkspaceState("ws-alpha", ws1State);

    const { storeServices } = createMockServices();

    // Render store for an unpopulated workspace ID "ws-beta"
    const { result } = renderHook(() =>
      useWorkspaceStore({ workspaceId: "ws-beta", services: storeServices }),
    );

    // "ws-beta" must NOT inherit "ws-alpha"'s HMR state
    expect(result.current.state.layout.tabs).toHaveLength(0);
    expect(result.current.state.activeWorktreePath).toBeNull();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
  createSession,
  flushAnimationFrames,
  mocks,
  setupTerminalHostTestEnv,
} from "./terminalHostManagerTestHelper";
import { terminalEventBus } from "./terminalEvents";
import { MAX_PENDING_OUTPUT_CHARS, terminalHostManager } from "./terminalHostManager";

describe("terminalHostManager output scheduling & batching", () => {
  beforeEach(() => {
    setupTerminalHostTestEnv();
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("unsubscribes previous backendSessionId output subscription when backendSessionId changes in updateSession", async () => {
    const session = createSession("sess-update", "backend-old");
    const unreg = terminalHostManager.registerVisible("sess-update");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;
    mocks.emitSessionOutput("backend-old", "hello old");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello old");

    mocks.terminalWrites.length = 0;
    const updatedSession = createSession("sess-update", "backend-new");
    terminalHostManager.updateSession("sess-update", updatedSession);

    // Old backend session output must NOT be written anymore
    mocks.emitSessionOutput("backend-old", "old after update");
    flushAnimationFrames();
    expect(mocks.terminalWrites).not.toContain("old after update");

    // New backend session output MUST be written
    mocks.emitSessionOutput("backend-new", "hello new");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello new");

    unreg();
    terminalHostManager.destroy("sess-update");
  });

  it("batches same-frame output writes at animation-frame cadence into a single ordered terminal write", async () => {
    const session = createSession("sess-batched", "backend-batch");
    const unreg = terminalHostManager.registerVisible("sess-batched");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-batch", "chunk1-");
    mocks.emitSessionOutput("backend-batch", "chunk2-");
    mocks.emitSessionOutput("backend-batch", "chunk3");

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    // Flush animation frame
    flushAnimationFrames();

    // Exactly one write call with all 3 chunks in original order
    expect(mocks.terminalWrites).toEqual(["chunk1-chunk2-chunk3"]);

    unreg();
    terminalHostManager.destroy("sess-batched");
  });

  it("cancels pending batched output and prevents writes after destroy or updateSession rebinding", async () => {
    // 1. Teardown via destroy
    const session1 = createSession("sess-teardown-1", "backend-td-1");
    const unreg1 = terminalHostManager.registerVisible("sess-teardown-1");
    await terminalHostManager.getOrCreate(session1, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-1", "pending before destroy");
    unreg1();
    terminalHostManager.destroy("sess-teardown-1");

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Teardown via updateSession rebinding
    const session2 = createSession("sess-teardown-2", "backend-td-old");
    const unreg2 = terminalHostManager.registerVisible("sess-teardown-2");
    await terminalHostManager.getOrCreate(session2, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-old", "pending before rebind");
    const session2Updated = createSession("sess-teardown-2", "backend-td-new");
    terminalHostManager.updateSession("sess-teardown-2", session2Updated);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // New backend emits and flushes normally
    mocks.emitSessionOutput("backend-td-new", "live new");
    expect(mocks.terminalWrites).toHaveLength(0);
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["live new"]);

    unreg2();
    terminalHostManager.destroy("sess-teardown-2");
  });

  it("batches outputs per session independently without cross-session mixing", async () => {
    const session1 = createSession("sess-mix-1", "backend-mix-1");
    const session2 = createSession("sess-mix-2", "backend-mix-2");

    const unreg1 = terminalHostManager.registerVisible("sess-mix-1");
    const unreg2 = terminalHostManager.registerVisible("sess-mix-2");

    await terminalHostManager.getOrCreate(session1, true);
    await terminalHostManager.getOrCreate(session2, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-mix-1", "s1-a");
    mocks.emitSessionOutput("backend-mix-2", "s2-a");
    mocks.emitSessionOutput("backend-mix-1", "s1-b");
    mocks.emitSessionOutput("backend-mix-2", "s2-b");

    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();

    expect(mocks.terminalWrites).toEqual(["s1-as1-b", "s2-as2-b"]);

    unreg1();
    unreg2();
    terminalHostManager.destroy("sess-mix-1");
    terminalHostManager.destroy("sess-mix-2");
  });

  it("maintains replay-before-live ordering on initial subscription", async () => {
    const session = createSession("sess-replay", "backend-replay");
    const unreg = terminalHostManager.registerVisible("sess-replay");

    // Simulate backlog replay synchronously during subscribeOutput
    vi.spyOn(terminalEventBus, "subscribeOutput").mockImplementationOnce((sessionId: string, cb: (text: string) => void) => {
      let set = mocks.outputListeners.get(sessionId);
      if (!set) {
        set = new Set();
        mocks.outputListeners.set(sessionId, set);
      }
      set.add(cb);
      cb("replay-chunk-");
      return vi.fn(() => {
        set?.delete(cb);
        if (set?.size === 0) mocks.outputListeners.delete(sessionId);
      });
    });

    await terminalHostManager.getOrCreate(session, true);
    mocks.emitSessionOutput("backend-replay", "live-chunk");

    // Clear preview banner writes
    mocks.terminalWrites.length = 0;

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["replay-chunk-live-chunk"]);

    unreg();
    terminalHostManager.destroy("sess-replay");
  });

  it("synchronously flushes pending output when accumulated characters reach or exceed MAX_PENDING_OUTPUT_CHARS before rAF", async () => {
    const session = createSession("sess-cap", "backend-cap");
    const unreg = terminalHostManager.registerVisible("sess-cap");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    const halfCap = "A".repeat(MAX_PENDING_OUTPUT_CHARS / 2);
    const exceedCap = "B".repeat(MAX_PENDING_OUTPUT_CHARS / 2 + 10);
    const trailingChunk = "C".repeat(50);

    // 1. Below cap: queued without immediate write
    mocks.emitSessionOutput("backend-cap", halfCap);
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Reaching/exceeding cap: synchronously flushes accumulated batch immediately before rAF
    mocks.emitSessionOutput("backend-cap", exceedCap);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 3. New chunk arriving after flush is held for next rAF
    mocks.emitSessionOutput("backend-cap", trailingChunk);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 4. On rAF flush, trailing chunk is written in ordered sequence
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap, trailingChunk]);

    unreg();
    terminalHostManager.destroy("sess-cap");
  });
});

use crate::ipc::{run_blocking, IpcError};
use crate::worktree::{run_git, WorkspaceRegistry, WorktreeError, WorktreeManager};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use tauri::State;

/// Workspace ID that shipped as a hard-coded alias for the startup repository.
/// It is no longer registered. Clients that persisted it migrate by calling
/// [`cmd_project_initial`] on startup and adopting the canonical ID it returns.
pub const LEGACY_DEFAULT_WORKSPACE_ID: &str = "default";

/// Fallback ID for a root whose folder name carries no usable characters.
const FALLBACK_WORKSPACE_ID: &str = "project";

/// Derives the canonical workspace ID for a repository root from its folder
/// name, restricted to characters `WorkspaceRegistry::validate_workspace_id`
/// accepts (no separators, whitespace, control characters, or leading `-`).
pub fn derive_workspace_id(repo_root: &Path) -> String {
    repo_root
        .file_name()
        .and_then(|name| name.to_str())
        .map(|name| {
            let slug: String = name
                .chars()
                .map(|ch| {
                    if ch.is_alphanumeric() || ch == '_' || ch == '-' {
                        ch
                    } else {
                        '-'
                    }
                })
                .collect();
            let trimmed = slug.trim_matches('-');
            if trimmed.is_empty() {
                FALLBACK_WORKSPACE_ID.to_string()
            } else {
                trimmed.to_string()
            }
        })
        .unwrap_or_else(|| FALLBACK_WORKSPACE_ID.to_string())
}

/// Registers (idempotently) and returns the single canonical project for the
/// startup repository.
///
/// The ID is derived from the repository root reported by Git, not from the
/// process working directory, so launching from a subdirectory (`src-tauri/`,
/// a worktree checkout, a test harness) still yields one stable project ID.
pub fn initial_project(registry: &WorkspaceRegistry) -> Result<RegisteredProject, IpcError> {
    let cwd = std::env::current_dir().map_err(|error| {
        IpcError::from(WorktreeError::InvalidPath {
            path: PathBuf::from("."),
            reason: format!("the startup working directory is unavailable: {error}"),
        })
    })?;
    register_canonical_project(registry, &cwd, None)
}

/// Registers a repository root under exactly one workspace ID.
///
/// Canonical-root uniqueness: a root already registered under some ID resolves
/// to that existing project instead of gaining a second alias, so the registry
/// holds at most one ID per repository root. When `preferred_id` is `None` the
/// ID is derived from the root's folder name.
fn register_canonical_project(
    registry: &WorkspaceRegistry,
    repo_path: &Path,
    preferred_id: Option<&str>,
) -> Result<RegisteredProject, IpcError> {
    // `try_new` walks up to the Git top level, canonicalizes it, and rejects
    // non-Git paths, so the uniqueness check below compares canonical roots.
    let repo_root = WorktreeManager::try_new(repo_path)
        .map_err(IpcError::from)?
        .repo_root()
        .to_path_buf();

    if let Some((workspace_id, _)) = registry
        .list()
        .into_iter()
        .find(|(_, manager)| manager.repo_root() == repo_root)
    {
        return Ok(RegisteredProject {
            workspace_id,
            repo_root,
        });
    }

    let workspace_id = match preferred_id {
        Some(requested) => requested.to_string(),
        None => derive_workspace_id(&repo_root),
    };
    registry
        .register(&workspace_id, &repo_root)
        .map_err(IpcError::from)?;
    let repo_root = registry.repo_root(&workspace_id).map_err(IpcError::from)?;
    Ok(RegisteredProject {
        workspace_id,
        repo_root,
    })
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct RegisterProjectRequest {
    pub workspace_id: String,
    pub repo_path: PathBuf,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RegisteredProject {
    pub workspace_id: String,
    pub repo_root: PathBuf,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ProjectBranchesRequest {
    pub workspace_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LocalBranch {
    pub name: String,
    pub is_current: bool,
}

/// Registers a project, enforcing one workspace ID per canonical repository
/// root. Requesting a new ID for an already-registered root is not an error:
/// the existing project is returned, so a client holding a stale ID (such as
/// the legacy `default`) migrates onto the canonical one instead of creating a
/// duplicate alias. Callers must adopt the returned `workspaceId`.
#[tauri::command]
pub async fn cmd_project_register(
    registry: State<'_, WorkspaceRegistry>,
    request: RegisterProjectRequest,
) -> Result<RegisteredProject, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        register_canonical_project(
            &registry,
            &request.repo_path,
            Some(request.workspace_id.as_str()),
        )
    })
    .await
}

/// Returns the one canonical project for the repository the app was started
/// from, registering it on first call. Replaces the previous startup behaviour
/// of registering both a derived ID and a `default` alias for the same root.
#[tauri::command]
pub async fn cmd_project_initial(
    registry: State<'_, WorkspaceRegistry>,
) -> Result<RegisteredProject, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || initial_project(&registry)).await
}

#[tauri::command]
pub async fn cmd_project_branches(
    registry: State<'_, WorkspaceRegistry>,
    request: ProjectBranchesRequest,
) -> Result<Vec<LocalBranch>, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let manager = registry
            .manager(&request.workspace_id)
            .map_err(IpcError::from)?;
        let branch_output = run_git(
            manager.repo_root(),
            &[
                "for-each-ref",
                "--sort=refname",
                "--format=%(refname:short)",
                "refs/heads/",
            ],
        )
        .map_err(IpcError::from)?;
        let current_output =
            run_git(manager.repo_root(), &["branch", "--show-current"]).map_err(IpcError::from)?;
        let current = current_output.trim();

        let mut branches = branch_output
            .lines()
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(|name| LocalBranch {
                name: name.to_string(),
                is_current: !current.is_empty() && name == current,
            })
            .collect::<Vec<_>>();
        branches.sort_by(|left, right| left.name.cmp(&right.name));
        Ok(branches)
    })
    .await
}

