pub(crate) struct PtySessionConfig {
    pub id: String,
    pub master: Box<dyn MasterPty + Send>,
    pub child: Box<dyn Child + Send + Sync>,
    pub writer: Box<dyn Write + Send>,
    pub reader: Box<dyn Read + Send>,
    pub cols: u16,
    pub rows: u16,
    pub tx: mpsc::Sender<Vec<u8>>,
    /// Canonical worktree/repository root that owns this interactive terminal.
    ///
    /// Interactive terminals are intentionally *not* exclusive worktree writers: Orca
    /// allows several PTYs in the same worktree.  Keeping the ownership path directly on
    /// the PTY session preserves session listing and CWD validation without abusing the
    /// exclusive writer lease used by agent/destructive-operation safety.
    pub worktree_path: Option<PathBuf>,
}

pub struct PtySession {
    pub id: String,
    master: Arc<Mutex<Option<Box<dyn MasterPty + Send>>>>,
    writer: Arc<Mutex<Option<Box<dyn Write + Send>>>>,
    child: Arc<Mutex<Option<Box<dyn Child + Send + Sync>>>>,
    reader_task: Arc<Mutex<Option<JoinHandle<()>>>>,
    output_tx: Arc<Mutex<Option<mpsc::Sender<Vec<u8>>>>>,
    worktree_path: Option<PathBuf>,
    reader_finished: Arc<AtomicBool>,
    reaped: Arc<AtomicBool>,
    state: Arc<Mutex<PtySessionState>>,
    cols: Arc<Mutex<u16>>,
    rows: Arc<Mutex<u16>>,
}

impl PtySession {
    pub(crate) fn new(config: PtySessionConfig) -> Self {
        let output_tx = Arc::new(Mutex::new(Some(config.tx)));
        let reader_tx = output_tx
            .lock()
            .as_ref()
            .expect("output sender must exist while starting reader")
            .clone();
        let reader = config.reader;
        let reader_finished = Arc::new(AtomicBool::new(false));
        let reader_finished_task = Arc::clone(&reader_finished);
        let reader_task = tokio::task::spawn_blocking(move || {
            let mut reader = reader;
            let mut buf = [0u8; 4096];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        if reader_tx.blocking_send(buf[..n].to_vec()).is_err() {
                            break;
                        }
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(_) => break,
                }
            }
            reader_finished_task.store(true, Ordering::Release);
        });

        Self {
            id: config.id,
            master: Arc::new(Mutex::new(Some(config.master))),
            writer: Arc::new(Mutex::new(Some(config.writer))),
            child: Arc::new(Mutex::new(Some(config.child))),
            reader_task: Arc::new(Mutex::new(Some(reader_task))),
            output_tx,
            worktree_path: config.worktree_path,
            reader_finished,
            reaped: Arc::new(AtomicBool::new(false)),
            state: Arc::new(Mutex::new(PtySessionState::Starting)),
            cols: Arc::new(Mutex::new(config.cols)),
            rows: Arc::new(Mutex::new(config.rows)),
        }
    }

    pub fn id(&self) -> &str {
        &self.id
    }

    pub fn state(&self) -> PtySessionState {
        self.state.lock().clone()
    }

    pub(crate) fn mark_running(&self) {
        let mut state = self.state.lock();
        if matches!(*state, PtySessionState::Starting) {
            *state = PtySessionState::Running;
        }
    }

    pub(crate) fn begin_closing(&self) -> bool {
        let mut state = self.state.lock();
        match *state {
            PtySessionState::Starting | PtySessionState::Running => {
                *state = PtySessionState::Closing;
                true
            }
            PtySessionState::Closing
            | PtySessionState::Exited { .. }
            | PtySessionState::Failed { .. } => false,
        }
    }

    pub(crate) fn mark_exited(&self, code: Option<i32>) {
        *self.state.lock() = PtySessionState::Exited { code };
    }

    pub(crate) fn mark_failed(&self, reason: impl Into<String>) {
        *self.state.lock() = PtySessionState::Failed {
            reason: reason.into(),
        };
    }

    pub fn pid(&self) -> Option<u32> {
        self.child
            .lock()
            .as_ref()
            .and_then(|child| child.process_id())
    }

    pub fn worktree_path(&self) -> Option<PathBuf> {
        self.worktree_path.clone()
    }

    pub fn write_input(&self, data: &[u8]) -> Result<(), PtyError> {
        let mut writer = self.writer.lock();
        let writer = writer
            .as_mut()
            .ok_or_else(|| PtyError::IoError("PTY writer is closed".into()))?;
        writer
            .write_all(data)
            .map_err(|e| PtyError::IoError(format!("Write failed: {e}")))?;
        writer
            .flush()
            .map_err(|e| PtyError::IoError(format!("Flush failed: {e}")))?;
        Ok(())
    }

    pub fn resize(&self, cols: u16, rows: u16) -> Result<(), PtyError> {
        let size = PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        };
        let master = self.master.lock();
        let master = master
            .as_ref()
            .ok_or_else(|| PtyError::ResizeError("PTY master is closed".into()))?;
        master
            .resize(size)
            .map_err(|e| PtyError::ResizeError(format!("Resize failed: {e}")))?;
        *self.cols.lock() = cols;
        *self.rows.lock() = rows;
        Ok(())
    }

    pub fn get_size(&self) -> (u16, u16) {
        (*self.cols.lock(), *self.rows.lock())
    }

    pub fn kill(&self) -> Result<(), PtyError> {
        let mut child = self.child.lock();
        let Some(child) = child.as_mut() else {
            return Ok(());
        };
        child
            .kill()
            .map_err(|e| PtyError::KillError(format!("Kill failed: {e}")))
    }

    #[cfg(unix)]
    pub fn signal(&self, signal: TerminalSignal) -> Result<(), PtyError> {
        if signal == TerminalSignal::Interrupt {
            // A literal VINTR byte goes through the PTY line discipline, which directs
            // SIGINT to the terminal's current foreground process group.
            return self.write_input(&[0x03]);
        }

        let pid = self
            .pid()
            .ok_or_else(|| PtyError::KillError("PID not available for signal".into()))?;
        let sig = match signal {
            TerminalSignal::Interrupt => libc::SIGINT,
            TerminalSignal::Terminate => libc::SIGTERM,
            TerminalSignal::Kill => libc::SIGKILL,
        };

        // portable-pty creates the child as the PTY session/process-group leader on Unix.
        // Addressing the negative pid signals the whole job-control process group rather
        // than only the shell process.
        let result = unsafe { libc::kill(-(pid as i32), sig) };
        if result == 0 {
            return Ok(());
        }

        Err(PtyError::KillError(format!(
            "Failed to send signal {signal:?} to process group {pid}: {}",
            std::io::Error::last_os_error()
        )))
    }

    #[cfg(not(unix))]
    pub fn signal(&self, signal: TerminalSignal) -> Result<(), PtyError> {
        match signal {
            TerminalSignal::Interrupt | TerminalSignal::Terminate | TerminalSignal::Kill => {
                self.kill()
            }
        }
    }

    pub(crate) fn poll_exit_code(&self) -> Result<Option<i32>, PtyError> {
        let mut child_slot = self.child.lock();
        let Some(child) = child_slot.as_mut() else {
            return Ok(match self.state() {
                PtySessionState::Exited { code } => code,
                _ => None,
            });
        };

        let status = child
            .try_wait()
            .map_err(|e| PtyError::Other(format!("try_wait failed: {e}")))?;
        let Some(status) = status else {
            return Ok(None);
        };

        let code = status.exit_code() as i32;
        child_slot.take();
        self.reaped.store(true, Ordering::Release);
        Ok(Some(code))
    }

    pub(crate) fn wait_and_reap(&self) -> Result<Option<i32>, PtyError> {
        let mut child_slot = self.child.lock();
        let Some(mut child) = child_slot.take() else {
            return Ok(match self.state() {
                PtySessionState::Exited { code } => code,
                _ => None,
            });
        };

        let result = child
            .wait()
            .map(|status| Some(status.exit_code() as i32))
            .map_err(|e| PtyError::Other(format!("wait failed: {e}")));
        self.reaped.store(true, Ordering::Release);
        result
    }

    pub fn is_alive(&self) -> bool {
        matches!(self.poll_exit_code(), Ok(None)) && !self.is_reaped()
    }

    pub fn is_reaped(&self) -> bool {
        self.reaped.load(Ordering::Acquire)
    }

    pub fn is_reader_finished(&self) -> bool {
        self.reader_finished.load(Ordering::Acquire)
    }

    pub(crate) fn output_receiver_closed(&self) -> bool {
        self.output_tx
            .lock()
            .as_ref()
            .map(mpsc::Sender::is_closed)
            .unwrap_or(true)
    }

    pub(crate) fn close_output(&self) {
        self.output_tx.lock().take();
    }

    pub(crate) fn close_io(&self) {
        self.writer.lock().take();
        self.master.lock().take();
    }

    pub(crate) fn take_reader_task(&self) -> Option<JoinHandle<()>> {
        self.reader_task.lock().take()
    }
}

impl Drop for PtySession {
    fn drop(&mut self) {
        self.writer.lock().take();
        self.master.lock().take();
        self.output_tx.lock().take();
        if let Some(handle) = self.reader_task.lock().take() {
            handle.abort();
        }
    }
}

import type { FitAddon } from "@xterm/addon-fit";
import type { SearchAddon } from "@xterm/addon-search";
import type { Terminal } from "@xterm/xterm";

import { isTauriRuntime, resizeTerminal, writeTerminal } from "./tauri";
import { attachScheduledOutputSubscription } from "./terminalOutputScheduler";
import { attachWebglRenderer, loadTerminalAssets } from "./terminalRenderer";
import {
  FALLBACK_PREFERENCES,
  fetchCachedNativePreferences,
  loadTerminalSettings,
  resolveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type TerminalInstance = {
  element: HTMLDivElement;
  terminal: Terminal;
  fitAddon: FitAddon;
  searchAddon: SearchAddon;
  disposeWebgl: () => void;
  resizeObserver: ResizeObserver;
  disposables: Array<() => void>;
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  unsubscribeOutput?: () => void;
};

export type CreateTerminalInstanceOptions = {
  session: TerminalSession;
  active: boolean;
  isVisible: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  getInstance: (sessionId: string) => TerminalInstance | undefined;
};

type TerminalViewport = {
  readonly buffer: {
    readonly active: {
      readonly baseY: number;
      readonly viewportY: number;
    };
  };
  scrollToBottom(): void;
};

export function fitTerminal(terminal: TerminalViewport, fitAddon: Pick<FitAddon, "fit">): void {
  const wasAtBottom = terminal.buffer.active.viewportY === terminal.buffer.active.baseY;
  fitAddon.fit();
  if (wasAtBottom) {
    terminal.scrollToBottom();
  }
}

export function disposeTerminalInstance(inst: TerminalInstance): void {
  inst.resizeObserver.disconnect();
  inst.unsubscribeOutput?.();
  inst.unsubscribeOutput = undefined;
  for (const d of inst.disposables) d();
  inst.searchAddon.dispose();
  inst.disposeWebgl();
  inst.terminal.dispose();
  inst.element.remove();
}

export async function createTerminalInstance({
  session,
  active,
  isVisible,
  onBell,
  onTitleChange,
  getInstance,
}: CreateTerminalInstanceOptions): Promise<TerminalInstance> {
  const hostElement = document.createElement("div");
  hostElement.className = "terminal-host h-full w-full bg-terminal";
  hostElement.setAttribute("aria-label", `Terminal in ${session.cwd}`);
  Object.assign(hostElement.style, {
    position: "absolute",
    inset: "0px",
    width: "100%",
    height: "100%",
    minWidth: "0px",
    minHeight: "0px",
    overflow: "hidden",
  });

  const [latestNativePrefs, { Terminal: TerminalConstructor, FitAddon: FitAddonConstructor, Unicode11Addon, SearchAddon: SearchAddonConstructor }] =
    await Promise.all([
      Promise.race([
        fetchCachedNativePreferences(),
        new Promise<typeof FALLBACK_PREFERENCES>((resolve) =>
          setTimeout(() => resolve(FALLBACK_PREFERENCES), 200),
        ),
      ]),
      loadTerminalAssets(),
    ]);

  const finalSettings = resolveTerminalSettings(loadTerminalSettings(), latestNativePrefs);

  const terminal = new TerminalConstructor({
    allowProposedApi: false,
    customGlyphs: false,
    convertEol: true,
    cursorBlink: true,
    cursorStyle: finalSettings.cursorStyle ?? "block",
    fontFamily: finalSettings.fontFamily,
    fontSize: finalSettings.fontSize,
    lineHeight: 1.0,
    letterSpacing: 0,
    macOptionIsMeta: finalSettings.macosOptionAsAlt,
    scrollback: finalSettings.scrollback,
    theme: finalSettings.theme,
  });
  const fitAddon = new FitAddonConstructor();
  terminal.loadAddon(fitAddon);
  const searchAddon = new SearchAddonConstructor();
  terminal.loadAddon(searchAddon);
  if (Unicode11Addon) {
    try {
      const unicode11Addon = new Unicode11Addon();
      terminal.loadAddon(unicode11Addon);
      terminal.unicode.activeVersion = "11";
    } catch {
    }
  }
  terminal.open(hostElement);

  let disposeWebgl: () => void = () => undefined;
  void attachWebglRenderer(terminal).then((dispose) => {
    disposeWebgl = dispose;
  });

  let resizeFrame = 0;
  const resize = () => {
    cancelAnimationFrame(resizeFrame);
    resizeFrame = requestAnimationFrame(() => {
      if (hostElement.clientWidth === 0 || hostElement.clientHeight === 0) return;
      fitTerminal(terminal, fitAddon);
      const backendSessionId = session.backendSessionId;
      if (!backendSessionId) return;
      void resizeTerminal({ sessionId: backendSessionId, cols: terminal.cols, rows: terminal.rows }).catch(() => undefined);
    });
  };

  const resizeObserver = new ResizeObserver(resize);
  resizeObserver.observe(hostElement);

  const disposables: Array<() => void> = [];

  const dataDisposable = terminal.onData((data) => {
    const backendSessionId = session.backendSessionId;
    if (!backendSessionId) return;
    void writeTerminal({ sessionId: backendSessionId, data }).catch(() => undefined);
  });
  disposables.push(() => dataDisposable.dispose());

  const titleDisposable = terminal.onTitleChange((title) => {
    getInstance(session.id)?.onTitleChange?.(title);
  });
  disposables.push(() => titleDisposable.dispose());

  const bellDisposable = terminal.onBell(() => {
    getInstance(session.id)?.onBell?.();
  });
  disposables.push(() => bellDisposable.dispose());

  const focusTerminal = () => terminal.focus();
  hostElement.addEventListener("pointerdown", focusTerminal);
  disposables.push(() => hostElement.removeEventListener("pointerdown", focusTerminal));

  let unsubscribeOutput: (() => void) | undefined;
  if (isVisible && session.backendSessionId) {
    unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, terminal);
  }

  if (!isTauriRuntime()) {
    terminal.writeln("\x1b[1;32mFerryx\x1b[0m  UI preview");
    terminal.writeln("\x1b[90mLaunch through Tauri to attach the PTY session.\x1b[0m");
    terminal.write("\r\n\x1b[34m~\x1b[0m \x1b[32m❯\x1b[0m ");
  }

  resize();
  if (active) terminal.focus();

  return {
    element: hostElement,
    terminal,
    fitAddon,
    searchAddon,
    disposeWebgl,
    resizeObserver,
    disposables,
    session,
    active,
    onBell,
    onTitleChange,
    unsubscribeOutput,
  };
}

import type { Terminal } from "@xterm/xterm";

import { terminalEventBus } from "./terminalEvents";

export const MAX_PENDING_OUTPUT_CHARS = 128 * 1024;

type TerminalOutputWriter = Pick<Terminal, "write">;

/**
 * Batches incoming PTY output chunks per terminal renderer at animation-frame cadence.
 *
 * Queue policy:
 * - Chunks received between rAF flushes are held in an ordered per-renderer buffer.
 * - On frame flush, all buffered chunks coalesce into a single `terminal.write` call in original arrival order.
 * - If queued characters reach or exceed `MAX_PENDING_OUTPUT_CHARS` before rAF, the buffer is flushed synchronously
 *   to guarantee memory safety without loss or reordering.
 * - Replay backlog delivered synchronously during `subscribeOutput` is enqueued before subsequent live output.
 * - Teardown (via unlisten or manager destroy) immediately cancels pending rAF callbacks and clears buffered data,
 *   preventing stale or out-of-order writes after session rebinding or instance disposal.
 */
export function attachScheduledOutputSubscription(
  backendSessionId: string,
  terminal: TerminalOutputWriter,
): () => void {
  let outputBuffer: string[] = [];
  let outputBufferChars = 0;
  let outputFrame = 0;

  const flushOutput = () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    if (outputBuffer.length === 0) return;
    const coalesced = outputBuffer.length === 1 ? (outputBuffer[0] ?? "") : outputBuffer.join("");
    outputBuffer = [];
    outputBufferChars = 0;
    terminal.write(coalesced);
  };

  const unsubscribe = terminalEventBus.subscribeOutput(backendSessionId, (text) => {
    outputBuffer.push(text);
    outputBufferChars += text.length;

    if (outputBufferChars >= MAX_PENDING_OUTPUT_CHARS) {
      flushOutput();
    } else if (outputFrame === 0) {
      outputFrame = requestAnimationFrame(flushOutput);
    }
  });

  return () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    outputBuffer = [];
    outputBufferChars = 0;
    unsubscribe();
  };
}

import type { TerminalLifecyclePayload, TerminalOutputPayload } from "./types";
import { onTerminalLifecycle, onTerminalOutput } from "./tauri";
import { TerminalOutputDecoderRegistry } from "./terminalOutput";

const MAX_BACKLOG_CHARS = 512 * 1024;
const MAX_OSC_TITLE_CHARS = 8 * 1024;
const OSC_TITLE_START_RE = /\u001b\](?:0|1|2);/g;
const OSC_PARTIAL_PREFIXES = ["\u001b", "\u001b]", "\u001b]0", "\u001b]1", "\u001b]2"] as const;

type OutputListener = (text: string) => void;
type LifecycleListener = (payload: TerminalLifecyclePayload) => void;
type TitleListener = (sessionId: string, title: string) => void;

type SessionBacklog = {
  chunks: string[];
  totalChars: number;
};

export type OscTitleScanResult = {
  titles: string[];
  carry: string;
};

/**
 * Extracts OSC 0/1/2 terminal titles from decoded PTY output while preserving an incomplete
 * sequence for the next chunk. This runs independently of xterm, so background/unmounted tabs
 * still produce activity title updates.
 */
export function scanTerminalOscTitles(text: string, carry = ""): OscTitleScanResult {
  const source = `${carry}${text}`;
  const titles: string[] = [];
  let searchFrom = 0;

  OSC_TITLE_START_RE.lastIndex = 0;
  while (true) {
    OSC_TITLE_START_RE.lastIndex = searchFrom;
    const match = OSC_TITLE_START_RE.exec(source);
    if (!match) break;

    const valueStart = match.index + match[0].length;
    const terminator = findOscTerminator(source, valueStart);
    if (!terminator) {
      return {
        titles,
        carry: source.slice(Math.max(match.index, source.length - MAX_OSC_TITLE_CHARS)),
      };
    }

    titles.push(source.slice(valueStart, terminator.index));
    searchFrom = terminator.index + terminator.length;
  }

  return { titles, carry: findPartialOscPrefix(source.slice(searchFrom)) };
}

function findOscTerminator(source: string, from: number): { index: number; length: number } | null {
  const candidates = [
    { index: source.indexOf("\u0007", from), length: 1 },
    { index: source.indexOf("\u001b\\", from), length: 2 },
    { index: source.indexOf("\u009c", from), length: 1 },
  ].filter((candidate) => candidate.index >= 0);
  if (candidates.length === 0) return null;
  return candidates.reduce((earliest, candidate) => candidate.index < earliest.index ? candidate : earliest);
}

function findPartialOscPrefix(source: string): string {
  for (const prefix of [...OSC_PARTIAL_PREFIXES].sort((a, b) => b.length - a.length)) {
    if (source.endsWith(prefix)) return prefix;
  }
  return "";
}

class TerminalEventBus {
  private readonly decoderRegistry = new TerminalOutputDecoderRegistry();
  private readonly outputListeners = new Map<string, Set<OutputListener>>();
  private readonly lifecycleListeners = new Set<LifecycleListener>();
  private readonly titleListeners = new Set<TitleListener>();
  private readonly backlog = new Map<string, SessionBacklog>();
  private readonly titleCarry = new Map<string, string>();
  private readonly lastTitle = new Map<string, string>();
  private startPromise: Promise<void> | null = null;

  ensureStarted(): Promise<void> {
    if (this.startPromise) return this.startPromise;
    this.startPromise = Promise.all([
      onTerminalOutput((payload) => this.handleOutput(payload)),
      onTerminalLifecycle((payload) => this.handleLifecycle(payload)),
    ]).then(() => undefined);
    return this.startPromise;
  }

  subscribeOutput(sessionId: string, listener: OutputListener, replay = true) {
    const listeners = this.outputListeners.get(sessionId) ?? new Set<OutputListener>();
    listeners.add(listener);
    this.outputListeners.set(sessionId, listeners);

    if (replay) {
      const existing = this.backlog.get(sessionId);
      if (existing && existing.totalChars > 0) {
        listener(existing.chunks.join(""));
      }
    }

    return () => {
      const current = this.outputListeners.get(sessionId);
      current?.delete(listener);
      if (current?.size === 0) this.outputListeners.delete(sessionId);
    };
  }

  subscribeLifecycle(listener: LifecycleListener) {
    this.lifecycleListeners.add(listener);
    return () => {
      this.lifecycleListeners.delete(listener);
    };
  }

  subscribeTitle(listener: TitleListener) {
    this.titleListeners.add(listener);
    return () => {
      this.titleListeners.delete(listener);
    };
  }

  clearSession(sessionId: string) {
    this.decoderRegistry.reset(sessionId);
    this.backlog.delete(sessionId);
    this.outputListeners.delete(sessionId);
    this.titleCarry.delete(sessionId);
    this.lastTitle.delete(sessionId);
  }

  getBacklogMetricsForTest(sessionId?: string): { sessions: number; chunks: number; chars: number } {
    if (sessionId) {
      const entry = this.backlog.get(sessionId);
      if (!entry) return { sessions: 0, chunks: 0, chars: 0 };
      return {
        sessions: 1,
        chunks: entry.chunks.length,
        chars: entry.totalChars,
      };
    }
    let totalChunks = 0;
    let totalChars = 0;
    for (const entry of this.backlog.values()) {
      totalChunks += entry.chunks.length;
      totalChars += entry.totalChars;
    }
    return {
      sessions: this.backlog.size,
      chunks: totalChunks,
      chars: totalChars,
    };
  }

  private handleOutput(payload: TerminalOutputPayload) {
    const text = this.decoderRegistry.decode(payload.sessionId, payload.data);
    if (text) this.publishOutput(payload.sessionId, text);
  }

  private handleLifecycle(payload: TerminalLifecyclePayload) {
    if (payload.state === "exited" || payload.state === "failed") {
      const tail = this.decoderRegistry.finish(payload.sessionId);
      if (tail) this.publishOutput(payload.sessionId, tail);
    }
    for (const listener of this.lifecycleListeners) listener(payload);
  }

  private publishOutput(sessionId: string, text: string) {
    const scan = scanTerminalOscTitles(text, this.titleCarry.get(sessionId) ?? "");
    if (scan.carry) this.titleCarry.set(sessionId, scan.carry);
    else this.titleCarry.delete(sessionId);

    for (const title of scan.titles) {
      if (this.lastTitle.get(sessionId) === title) continue;
      this.lastTitle.set(sessionId, title);
      for (const listener of this.titleListeners) listener(sessionId, title);
    }

    if (text.length > 0) {
      let entry = this.backlog.get(sessionId);
      if (!entry) {
        entry = { chunks: [], totalChars: 0 };
        this.backlog.set(sessionId, entry);
      }

      entry.chunks.push(text);
      entry.totalChars += text.length;

      while (entry.totalChars > MAX_BACKLOG_CHARS && entry.chunks.length > 0) {
        const oldest = entry.chunks[0];
        if (oldest === undefined) break;
        const overflow = entry.totalChars - MAX_BACKLOG_CHARS;
        if (oldest.length <= overflow) {
          entry.chunks.shift();
          entry.totalChars -= oldest.length;
        } else {
          entry.chunks[0] = oldest.slice(overflow);
          entry.totalChars -= overflow;
          break;
        }
      }
    }

    for (const listener of this.outputListeners.get(sessionId) ?? []) listener(text);
  }
}

export const terminalEventBus = new TerminalEventBus();

export function getBacklogMetricsForTest(sessionId?: string) {
  return terminalEventBus.getBacklogMetricsForTest(sessionId);
}

export function ensureTerminalEvents() {
  return terminalEventBus.ensureStarted();
}

