 24	    pub fn push(&mut self, chunk: Vec<u8>) {
 25	        if chunk.is_empty() {
 26	            return;
 27	        }
 28	        self.current_size += chunk.len();
 29	        self.chunks.push_back(chunk);
 30	
 31	        while self.current_size > self.capacity && !self.chunks.is_empty() {
 32	            if let Some(front) = self.chunks.pop_front() {
 33	                self.current_size -= front.len();
 34	            }
 35	        }
 36	    }
 37	
 38	    pub fn snapshot(&self) -> Vec<u8> {
 39	        let mut out = Vec::with_capacity(self.current_size);
 40	        for chunk in &self.chunks {
 41	            out.extend_from_slice(chunk);
 42	        }
 43	        out
 44	    }
 45	}
