 64	impl TerminalOutputHub {
 65	    pub fn new(capacity: usize) -> Self {
 66	        Self {
 67	            sessions: Arc::new(RwLock::new(HashMap::new())),
 68	            capacity,
 69	        }
 70	    }
 71	
 72	    pub fn register_session(&self, session_id: &str) -> broadcast::Receiver<Vec<u8>> {
 73	        let (tx, rx) = broadcast::channel(BROADCAST_CAPACITY);
 74	        let hub = SessionHub {
 75	            buffer: BoundedBuffer::new(self.capacity),
 76	            sender: tx,
 77	        };
 78	        self.sessions
 79	            .write()
 80	            .insert(session_id.to_string(), Arc::new(RwLock::new(hub)));
 81	        rx
 82	    }
 83	
 84	    pub fn publish(&self, session_id: &str, chunk: Vec<u8>) {
 85	        let session_hub = {
 86	            let sessions = self.sessions.read();
 87	            sessions.get(session_id).cloned()
 88	        };
 89	
 90	        if let Some(hub) = session_hub {
 91	            let mut hub = hub.write();
 92	            hub.buffer.push(chunk.clone());
 93	            // It is okay if there are no active receivers; send returns Err in that case
 94	            let _ = hub.sender.send(chunk);
 95	        }
 96	    }
 97	
 98	    pub fn subscribe(&self, session_id: &str) -> Option<(Vec<u8>, broadcast::Receiver<Vec<u8>>)> {
 99	        let session_hub = {
100	            let sessions = self.sessions.read();
101	            sessions.get(session_id).cloned()
102	        }?;
103	
104	        let hub = session_hub.read();
105	        let history = hub.buffer.snapshot();
106	        let rx = hub.sender.subscribe();
107	        Some((history, rx))
108	    }
109	
110	    pub fn remove_session(&self, session_id: &str) {
111	        self.sessions.write().remove(session_id);
112	    }
113	
114	    pub fn has_session(&self, session_id: &str) -> bool {
115	        self.sessions.read().contains_key(session_id)
116	    }
117	}
