 92	  subscribeOutput(sessionId: string, listener: OutputListener, replay = true) {
 93	    const listeners = this.outputListeners.get(sessionId) ?? new Set<OutputListener>();
 94	    listeners.add(listener);
 95	    this.outputListeners.set(sessionId, listeners);
 96	
