100	        listener(existing.chunks.join(""));
101	      }
102	    }
103	
104	    return () => {
105	      const current = this.outputListeners.get(sessionId);
106	      current?.delete(listener);
107	      if (current?.size === 0) this.outputListeners.delete(sessionId);
108	    };
109	  }
