37	
38	        let mut line = String::new();
39	        reader.read_line(&mut line).await.unwrap();
40	        let resp: DaemonResponse = serde_json::from_str(line.trim()).unwrap();
41	        match resp {
42	            DaemonResponse::HandshakeOk { version, pid } => {
43	                assert_eq!(version, DAEMON_PROTOCOL_VERSION);
44	                assert!(pid > 0);
45	            }
46	            _ => panic!("Expected HandshakeOk"),
47	        }
