423	                0,
424	                info.as_mut_ptr().cast(),
425	                size,
426	            )
427	        };
428	        if ret <= 0 {
429	            return None;
430	        }
431	        // SAFETY: proc_pidinfo succeeded (ret > 0) and initialized `info`.
432	        let info = unsafe { info.assume_init() };
433	        let path_bytes = &info.pvi_cdir.vip_path;
434	        let nul_pos = path_bytes.iter().position(|&c| c == 0)?;
435	        if nul_pos == 0 {
436	            return None;
437	        }
438	        let cstr = unsafe { CStr::from_ptr(path_bytes.as_ptr()) };
