 20	pub fn get_runtime_dir() -> PathBuf {
 21	    let uid = unsafe { libc::getuid() };
 22	    let path = PathBuf::from(format!("/tmp/rorca-{uid}"));
 23	    let _ = fs::create_dir_all(&path);
 24	    if let Ok(metadata) = fs::metadata(&path) {
 25	        let mut permissions = metadata.permissions();
 26	        permissions.set_mode(0o700);
 27	        let _ = fs::set_permissions(&path, permissions);
 28	    }
 29	    path
 30	}
