 40	pub fn get_default_session_path() -> PathBuf {
 41	    if let Some(mut base) = dirs_next().or_else(dirs_fallback) {
 42	        base.push("rorca");
 43	        let _ = fs::create_dir_all(&base);
 44	        base.join("session_state.json")
 45	    } else {
 46	        get_runtime_dir().join("session_state.json")
 47	    }
 48	}
